import rawMoves from "@/data/moves.json";
import type { Move } from "@/lib/types";

/**
 * Gen 9 move data keyed by move id, generated by scripts/fetch-smogon-data.mjs
 * from @pkmn/dex (MIT, data derived from Pokémon Showdown).
 */
export const MOVES: Record<string, Move> = rawMoves as unknown as Record<string, Move>;

export function getMove(id: string): Move | undefined {
  return MOVES[id];
}

/** Damaging moves (power > 0) of the given type. */
export function damagingMovesOfType(type: string): Move[] {
  return Object.values(MOVES).filter((m) => m.power > 0 && m.type === type);
}
